-- Bots de arena devem permanecer disponíveis como referências fixas.
-- A regra de um único Digimon ativo continua valendo para jogadores reais,
-- mas não pode ser aplicada ao jogador de sistema que possui vários bots.
DROP INDEX IF EXISTS uq_digimons_one_active_per_player;
UPDATE digimons SET status = 'ACTIVE' WHERE is_bot = TRUE;
CREATE UNIQUE INDEX IF NOT EXISTS uq_digimons_one_active_per_player
    ON digimons (player_id)
    WHERE status = 'ACTIVE' AND is_bot = FALSE;

-- Cobertura contínua a partir do Ouro (1200+), incluindo Platina e Diamante.
-- Cada estágio recebe cinco bots por faixa de rating; bots ignoram a janela
-- de rating no matchmaking, mas continuam respeitando o alcance de estágio.
INSERT INTO digimons
    (id, player_id, name, type, stage, level, experience,
     hp, attack, defense, iv_hp, iv_attack, iv_defense,
     created_at, rarity, personality, energy, max_energy, last_energy_update,
     bits, rebirth_count, status, grade, arena_rating, arena_wins, arena_losses, is_bot)
